109	    /**
110	     * Returns the stored E.164 {@code telephone} formatted for humans: the recognized country code
111	     * (with its leading {@code '+'}), a space, then the national digits grouped in threes from the
112	     * left and separated by spaces (for example {@code '+61412345678'} renders as
113	     * {@code '+61 412 345 678'}). The split into country code and national number reuses
114	     * {@link #countryCodeOf(String)}, the single definition of that split. Returns {@code null} when
115	     * the owner has no telephone, and returns the raw E.164 value unchanged when it carries no
116	     * recognized country code. This is the single definition of an owner's human-readable telephone.
117	     *
118	     * @return the human-formatted telephone, or {@code null} when the owner has no telephone
119	     */
120	    @Transient
121	    public String getTelephoneDisplay() {
122	        if (this.telephone == null) {
123	            return null;
124	        }
125	        String countryCode = countryCodeOf(this.telephone);
126	        if (countryCode == null) {
127	            return this.telephone;
128	        }
129	        String national = this.telephone.substring(1 + countryCode.length());
130	        StringBuilder display = new StringBuilder("+").append(countryCode);
131	        for (int i = 0; i < national.length(); i += 3) {
132	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
133	        }
134	        return display.toString();
135	    }
