581	    /**
582	     * Return the Pet with the given name, or null if none found for this Owner.
583	     *
584	     * @param name to test
585	     * @return true if pet name is already in use
586	     */
587	    public Pet getPet(String name) {
588	        return getPet(name, false);
589	    }
590	
591	    /**
592	     * Return the Pet with the given name, or null if none found for this Owner.
593	     *
594	     * @param name to test
595	     * @return true if pet name is already in use
596	     */
597	    public Pet getPet(String name, boolean ignoreNew) {
598	        name = name.toLowerCase();
599	        for (Pet pet : getPetsInternal()) {
600	            if (!ignoreNew || !pet.isNew()) {
601	                String compName = pet.getName();
602	                compName = compName.toLowerCase();
603	                if (compName.equals(name)) {
604	                    return pet;
605	                }
606	            }
607	        }
