234	    /**
235	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
236	     * The address is normalized in place (so a required-field check that follows rejects an
237	     * address blank after normalization), the required fields are checked, the telephone and
238	     * email are normalized in place, and the resulting owner is rejected when its derived
239	     * identity key already belongs to another owner. Each rule
240	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
241	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
242	     * to be mapped and saved.
243	     *
244	     * @param ownerFieldsDto the submitted owner fields, normalized in place
245	     */
246	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
247	        applyAddress(ownerFieldsDto);
248	        validateRequiredFields(ownerFieldsDto);
249	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
250	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
251	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
252	        rejectDuplicateIdentity(ownerFieldsDto);
253	        rejectCityAtCapacity(ownerFieldsDto.getCity());
254	        rejectDailyLimitExceeded(registrationDate);
255	    }
256	
257	    /**
258	     * Applies an owner's address to the submitted fields, normalizing it in place into the
259	     * canonical form stored and returned for the owner. This is the single intake step that owns
260	     * how a submitted address becomes an owner's stored address: it delegates the transform to
261	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
262	     * the result back onto {@code ownerFieldsDto}. It runs ahead of {@link
263	     * #validateRequiredFields(OwnerFieldsDto)} so an address that is blank after normalization is
264	     * rejected by the required-field check that follows. Isolating the step here keeps {@link
265	     * #prepareNewOwner(OwnerFieldsDto, LocalDate)} a list of named intake steps and gives address
266	     * handling one place to grow.
267	     *
268	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
269	     */
270	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
271	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
272	    }
273	
274	    /**
275	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
276	     * falls on a business day. The date supplied on the request is used when present, otherwise the
277	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
278	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
279	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
280	     * membership number's year segment, the per-day create limit) is computed against.
281	     *
282	     * A supplied registration date later than the server's current date is rejected with an
283	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
284	     *
285	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
286	     * @return the effective registration date rolled forward to the next business day
287	     */
288	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
289	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
290	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
291	            throw new InvalidFieldsException(List.of("registrationDate"));
292	        }
293	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
294	        return toBusinessDay(effective);
295	    }
296	
297	    /**
298	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
299	     * following Monday, while a weekday is returned unchanged.
300	     *
301	     * @param date the date to adjust
302	     * @return the same date when it is a weekday, otherwise the next Monday
303	     */
304	    private LocalDate toBusinessDay(LocalDate date) {
305	        java.time.DayOfWeek day = date.getDayOfWeek();
306	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
307	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
308	        }
309	        return date;
310	    }
311	
312	    /**
313	     * The maximum number of owners that may be created on a single day. Once this many owners
314	     * already carry today's {@code registrationDate}, no further owner may be created today.
315	     */
316	    private static final long DAILY_OWNER_LIMIT = 100L;
317	
318	    /**
319	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
320	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
321	     * date the new owner would be stored with, so owners are capped per business day. When the limit
322	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
323	     * advice renders as a 429 Too Many Requests response.
324	     *
325	     * @param registrationDate the adjusted business-day registration date of the owner being created
326	     */
327	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
328	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
329	            throw new DailyOwnerLimitExceededException(registrationDate);
330	        }
331	    }
332	
333	    /**
334	     * Counts the existing owners whose adjusted business-day {@code registrationDate} equals the
335	     * given date. This is the single definition of the per-day owner count, shared by the per-day
336	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
337	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
338	     *
339	     * @param registrationDate the adjusted business-day registration date to count owners against
340	     * @return the number of existing owners carrying that registration date
341	     */
342	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
343	        return this.clinicService.findAllOwners().stream()
344	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
345	            .count();
346	    }
347	
348	    /**
349	     * The number of owners that may carry a single day's {@code registrationDate} before that day
350	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
351	     * the create and read responses report {@code bulkSignupWarning} true for that date.
352	     */
353	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
354	
355	    /**
356	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
357	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
358	     * count is taken against the same adjusted date owners are stored with, mirroring the
359	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
360	     *
361	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
362	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
363	     */
364	    private boolean bulkSignupWarning(LocalDate registrationDate) {
365	        if (registrationDate == null) {
366	            return false;
367	        }
368	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
369	    }
370	
371	    /**
372	     * The maximum number of owners a single city may hold. Once a city already contains this
373	     * many owners, no further owner may be created in it.
374	     */
375	    private static final long CITY_OWNER_CAPACITY = 50L;
376	
377	    /**
378	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
379	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
380	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
381	     * which the exception advice renders as a 409 Conflict response.
382	     *
383	     * @param city the city of the owner being created
384	     */
385	    private void rejectCityAtCapacity(String city) {
386	        long count = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
388	            .count();
389	        if (count >= CITY_OWNER_CAPACITY) {
390	            throw new CityCapacityExceededException(city);
391	        }
392	    }
393	
394	    /**
395	     * Builds the customer code assigned to a newly created owner. The code is formatted as
396	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
397	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
398	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
399	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
400	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
401	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
402	     * identity scheme needs.
403	     *
404	     * @param owner the owner being created, whose fields the code is derived from
405	     * @return the formatted customer code
406	     */
407	    private String customerCodeFor(Owner owner) {
408	        String region = owner.getRegion();
409	        String regionCode = region != null ? region : "UNKNOWN";
410	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
411	        return deduplicateCustomerCode(regionCode + "-" + hash8);
412	    }
413	
414	    /**
415	     * Ensures the computed {@code customerCode} is unique across existing owners. When the given base
416	     * code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is appended with the
417	     * smallest {@code n} of 2 or more that yields a code no existing owner already carries.
418	     *
419	     * @param baseCode the customer code computed for the owner being created
420	     * @return the base code when it is already unique, otherwise the de-duplicated code
421	     */
422	    private String deduplicateCustomerCode(String baseCode) {
423	        Set<String> existing = this.clinicService.findAllOwners().stream()
424	            .map(Owner::getCustomerCode)
425	            .filter(Objects::nonNull)
426	            .collect(Collectors.toSet());
427	        if (!existing.contains(baseCode)) {
428	            return baseCode;
429	        }
430	        int n = 2;
431	        while (existing.contains(baseCode + "-" + n)) {
432	            n++;
433	        }
434	        return baseCode + "-" + n;
435	    }
436	
437	    /**
438	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
439	     * with the owner being created, compared case-insensitively. The count is taken before the
440	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
441	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
442	     *
443	     * @param firstName the first name of the owner being created
444	     * @param lastName the last name of the owner being created
445	     * @return the number of pre-existing owners sharing the same first and last name
446	     */
447	    private int countNamesakes(String firstName, String lastName) {
448	        return (int) this.clinicService.findAllOwners().stream()
449	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
450	                && lastName.equalsIgnoreCase(existing.getLastName()))
451	            .count();
452	    }
453	
454	    /**
455	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
456	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
457	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
458	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
459	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
460	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
461	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
462	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
463	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
464	     * postcode and is never a possible duplicate.
465	     *
466	     * @param owner the owner being created, already carrying its normalized telephone and postcode
467	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
468	     */
469	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
470	        owner.setPossibleDuplicate(false);
471	        owner.setPossibleDuplicateOf(null);
472	        if (sharesHousehold(ownerFieldsDto)) {
473	            return;
474	        }
475	        findPossibleDuplicate(owner).ifPresent(existing -> {
476	            owner.setPossibleDuplicate(true);
477	            owner.setPossibleDuplicateOf(existing.getId());
478	        });
479	    }
480	
481	    /**
482	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
483	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
484	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
485	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
486	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
487	     * {@link java.util.Optional#empty()} is returned.
488	     *
489	     * @param owner the owner being created, already carrying its normalized telephone and postcode
490	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
491	     */
492	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
493	        if (owner.getPostcode() == null) {
494	            return java.util.Optional.empty();
495	        }
496	        return this.clinicService.findAllOwners().stream()
497	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
498	                && owner.getPostcode().equals(existing.getPostcode())
499	                && !owner.getTelephone().equals(existing.getTelephone()))
500	            .findFirst();
501	    }
502	
503	    /**
504	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
505	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
506	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
507	     * the names of every offending field, which the exception advice renders as a 400 response
508	     * with an {@code errors} array.
509	     *
510	     * @param ownerFieldsDto the submitted owner fields
511	     */
512	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
513	        List<String> missing = new ArrayList<>();
514	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
515	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
516	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
517	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
518	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
519	        if (!missing.isEmpty()) {
520	            throw new RequiredFieldsMissingException(missing);
521	        }
522	    }
523	
524	    private void addIfBlank(List<String> missing, String fieldName, String value) {
525	        if (value == null || value.isBlank()) {
526	            missing.add(fieldName);
527	        }
528	    }
529	
530	    /**
531	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
532	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
533	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
534	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
535	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
536	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
537	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
538	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
539	     *
540	     * @param telephone the submitted telephone value
541	     * @return the normalized E.164 telephone
542	     */
543	    private String normalizeTelephone(String telephone) {
544	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
545	        String e164;
546	        if (cleaned.startsWith("+")) {
547	            e164 = "+" + cleaned.substring(1);
548	        } else {
549	            String national = cleaned;
550	            if (national.startsWith("0")) {
551	                national = national.substring(1);
552	            }
553	            e164 = "+61" + national;
554	        }
555	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
556	            throw new InvalidFieldsException(List.of("telephone"));
557	        }
558	        validateNationalNumberLength(e164);
559	        return e164;
560	    }
561	
562	    /**
563	     * Validates the national-number length of an already syntactically valid E.164 telephone
564	     * against its country code. When the number carries a country code this application recognizes
565	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
566	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
567	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
568	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
569	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
570	     * that is not recognized carries no per-country length rule and is left to the general
571	     * 8-to-15-digit E.164 check.
572	     *
573	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
574	     */
575	    private void validateNationalNumberLength(String e164) {
576	        String countryCode = Owner.countryCodeOf(e164);
577	        if (countryCode == null) {
578	            return;
579	        }
580	        int nationalLength = e164.length() - 1 - countryCode.length();
581	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
582	            throw new InvalidFieldsException(List.of("telephone"));
583	        }
584	    }
585	
586	    /**
587	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
588	     * and a domain containing at least one dot, none of the parts holding whitespace or a
589	     * second {@code @}.
590	     */
591	    private static final java.util.regex.Pattern EMAIL_PATTERN =
592	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
593	
594	    /**
595	     * Disposable email domains an owner may not register with. An email whose domain (compared
596	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
597	     */
598	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
599	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
600	
601	    /**
602	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
603	     * accepted and returned unchanged. When present it must be a syntactically valid address
604	     * whose domain is not on the disposable-domain blocklist (see
605	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
606	     * present but syntactically invalid or on a disposable domain an
607	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
608	     * response naming the {@code email} field.
609	     *
610	     * @param email the submitted email value, or {@code null} when omitted
611	     * @return the lower-cased email, or {@code null} when none was supplied
612	     */
613	    private String normalizeEmail(String email) {
614	        if (email == null) {
615	            return null;
616	        }
617	        String trimmed = email.trim();
618	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
619	            throw new InvalidFieldsException(List.of("email"));
620	        }
621	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
622	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
623	            throw new InvalidFieldsException(List.of("email"));
624	        }
625	        return canonicalEmail(trimmed);
626	    }
627	
628	    /**
629	     * Reduces an email to the canonical form used both to store it and to compare it against
630	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
631	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
632	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
633	     * value read back off an existing owner without risk of rejecting it. This is the single
634	     * definition of email identity: two emails denote the same address exactly when they
635	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
636	     * an email already on an existing owner can be compared for equality after both pass through
637	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
638	     *
639	     * @param email the email to canonicalize, or {@code null} when none was supplied
640	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
641	     */
642	    private String canonicalEmail(String email) {
643	        if (email == null) {
644	            return null;
645	        }
646	        return email.trim().toLowerCase(java.util.Locale.ROOT);
647	    }
648	
649	    /**
650	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
651	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
652	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
653	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
654	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
655	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
656	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
657	     * 400 response naming the {@code postcode} field.
658	     *
659	     * @param postcode the submitted postcode, or {@code null} when omitted
660	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
661	     */
662	    private void validatePostcode(String postcode, String city) {
663	        if (postcode == null) {
664	            return;
665	        }
666	        if (!postcode.matches("^[0-9]{4}$")) {
667	            throw new InvalidFieldsException(List.of("postcode"));
668	        }
669	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
670	        if (range != null) {
671	            int value = Integer.parseInt(postcode);
672	            if (value < range[0] || value > range[1]) {
673	                throw new InvalidFieldsException(List.of("postcode"));
674	            }
675	        }
676	    }
677	
678	    /**
679	     * Rejects a new owner that would join a household already occupied by an existing owner. The
680	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
681	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
682	     * two owners sharing a last name and postcode belong to the same household. When any existing
683	     * owner already carries that household identifier the new owner is a household duplicate and a
684	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
685	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
686	     * that household and bypasses this block, so it is created rather than rejected. An owner without
687	     * a postcode belongs to no shared household and is never a household duplicate.
688	     *
689	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
690	     */
691	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
692	        if (sharesHousehold(ownerFieldsDto)) {
693	            return;
694	        }
695	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
696	        if (householdId == null) {
697	            return;
698	        }
699	        boolean taken = this.clinicService.findAllOwners().stream()
700	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
701	        if (taken) {
702	            throw new DuplicateIdentityException(householdId);
703	        }
704	    }
705	
706	    /**
707	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
708	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
709	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
710	     * resolves to the same stable value automatically, without any explicit linking. An owner without
711	     * a postcode belongs to no shared household and is left without a household identifier.
712	     *
713	     * @param owner the newly created owner, mutated in place with its household identifier
714	     */
715	    private void assignHousehold(Owner owner) {
716	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
717	    }
718	
719	    /**
720	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
721	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
722	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
723	     * every rule that treats a declared household member differently from an independent owner.
724	     *
725	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
726	     * @return {@code true} when the request opted into sharing a household
727	     */
728	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
729	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
730	    }
731	
732	    /**
733	     * Derives the stable {@code householdId} shared by every owner in the household identified by
734	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
735	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
736	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
737	     * postcode — regardless of creation order or address — resolve to the same identifier
738	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
739	     * returned.
740	     *
741	     * @param lastName the household's last name
742	     * @param postcode the household's postcode, or {@code null} when the owner has none
743	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
744	     */
745	    private String householdIdFor(String lastName, String postcode) {
746	        if (postcode == null) {
747	            return null;
748	        }
749	        return shaHex(householdKey(lastName, postcode), 12);
750	    }
751	
752	    /**
753	     * Builds the canonical household key that identifies the household a {@code lastName} and
754	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
755	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
756	     * owner fields make up a household and how they are normalized;
757	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
758	     * owners in the same household resolve to the same key and therefore the same identifier.
759	     *
760	     * @param lastName the household's last name
761	     * @param postcode the household's postcode
762	     * @return the normalized household key
763	     */
764	    private String householdKey(String lastName, String postcode) {
765	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
766	    }
767	
768	    /**
769	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
770	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
771	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
772	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
773	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
774	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
775	     * an {@link IllegalStateException} is thrown.
776	     *
777	     * @param input the string to hash
778	     * @param hexChars the number of leading upper-case hex characters to return
779	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
780	     */
781	    private String shaHex(String input, int hexChars) {
782	        try {
783	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
784	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
785	            StringBuilder sb = new StringBuilder();
786	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
787	                sb.append(String.format("%02X", digest[i]));
788	            }
789	            return sb.substring(0, hexChars);
790	        }
791	        catch (java.security.NoSuchAlgorithmException e) {
792	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
793	        }
794	    }
795	
796	    /**
797	     * Counts the owners that belong to the household identified by the given {@code householdId},
798	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
799	     * of owners, so after a create it reflects the household's size including the newly persisted
800	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
801	     * household and yields {@code 0}.
802	     *
803	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
804	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
805	     */
806	    private int countHouseholdMembers(String householdId) {
807	        if (householdId == null) {
808	            return 0;
809	        }
810	        return (int) this.clinicService.findAllOwners().stream()
811	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
812	            .count();
813	    }
814	
815	    /**
816	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
817	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
818	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
819	     *
820	     * @param value the value to collapse, or {@code null}
821	     * @return the whitespace-collapsed value, never {@code null}
822	     */
823	    private String collapseWhitespace(String value) {
824	        if (value == null) {
825	            return "";
826	        }
827	        return value.trim().replaceAll("\\s+", " ");
828	    }
829	
830	    /**
831	     * Common street-type abbreviations expanded during address normalization, keyed by their
832	     * upper-cased token.
833	     */
834	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
835	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
836	
837	    /**
838	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
839	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
840	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
841	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
842	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
843	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
844	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
845	     * everywhere an address is stored or compared.
846	     *
847	     * @param address the submitted address value, or {@code null}
848	     * @return the normalized address, never {@code null}
849	     */
850	    private String normalizeAddress(String address) {
851	        if (address == null) {
852	            return "";
853	        }
854	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
855	        if (collapsed.isEmpty()) {
856	            return "";
857	        }
858	        String[] tokens = collapsed.split(" ");
859	        StringBuilder sb = new StringBuilder(collapsed.length());
860	        for (int i = 0; i < tokens.length; i++) {
861	            if (i > 0) {
862	                sb.append(' ');
863	            }
864	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
865	        }
866	        return sb.toString();
867	    }
868	}
